def test():
    N=22
    fixed={11:8,16:14,18:11,21:13}
    cols=set(); diag1=set(); diag2=set(); sol=[None]*N
    for r,c in fixed.items():
        sol[r]=c; cols.add(c); diag1.add(r-c); diag2.add(r+c)
    rows=[r for r in range(N) if r not in fixed]
    def backtrack(i):
        if i==len(rows):
            return True
        r=rows[i]
        for c in range(N):
            if c in cols or (r-c) in diag1 or (r+c) in diag2:
                continue
            cols.add(c); diag1.add(r-c); diag2.add(r+c); sol[r]=c
            if backtrack(i+1):
                return True
            cols.remove(c); diag1.remove(r-c); diag2.remove(r+c); sol[r]=None
        return False
    ok=backtrack(0)
    print(ok, sol)

test()
